mapper.select:
SELECT sr.id, sr.reservation_no AS reservationNo, sr.user_id AS userId, sr.spot_id AS spotId, sr.visit_date AS visitDate, sr.visit_time_slot AS visitTimeSlot, sr.visitor_count AS visitorCount, sr.contact_name AS contactName, sr.contact_mobile AS contactMobile, sr.status, sr.qr_token_hash AS qrTokenHash, sr.qr_expires_at AS qrExpiresAt, sr.verified_count AS verifiedCount, sr.remark, sr.created_at AS createdAt, sr.updated_at AS updatedAt, ss.name AS spotName, ss.address AS spotAddress, ss.opening_hours AS spotOpeningHours, ss.images AS spotImages, ss.status AS spotStatus, sc.id AS categoryId, sc.name AS categoryName, sc.code AS categoryCode, sc.icon_url AS categoryIconUrl FROM scenic_reservation sr LEFT JOIN scenic_spot ss ON sr.spot_id = ss.id LEFT JOIN scenic_category sc ON ss.category_id = sc.id WHERE 1 = 1
AND sr.reservation_no LIKE CONCAT('%',#{scenicReservation.reservationNo},'%')
AND sr.user_id = #{scenicReservation.userId}
AND sr.spot_id = #{scenicReservation.spotId}
AND sr.contact_name LIKE CONCAT('%',#{scenicReservation.contactName},'%')
AND sr.contact_mobile LIKE CONCAT('%',#{scenicReservation.contactMobile},'%')
AND sr.status = #{scenicReservation.status}
ORDER BY sr.created_at DESC
